from datetime import date, timedelta
import calendar


def recur(start: str, rule: str, count: int) -> list[str]:
    start_date = date.fromisoformat(start)
    parts = rule.split()
    kind = parts[0]
    interval = int(parts[1])
    results = []

    if kind == "DAILY":
        current = start_date
        for _ in range(count):
            results.append(current.isoformat())
            current += timedelta(days=interval)
        return results

    if kind == "WEEKLY":
        weekday_numbers = {
            "MO": 0, "TU": 1, "WE": 2, "TH": 3,
            "FR": 4, "SA": 5, "SU": 6,
        }
        weekdays = sorted(weekday_numbers[code] for code in parts[2].split(","))
        week_start = start_date - timedelta(days=start_date.weekday())
        week_index = 0

        while len(results) < count:
            active_week = week_start + timedelta(weeks=week_index * interval)
            for weekday in weekdays:
                candidate = active_week + timedelta(days=weekday)
                if candidate >= start_date:
                    results.append(candidate.isoformat())
                    if len(results) == count:
                        return results
            week_index += 1

    if kind == "MONTHLY":
        start_month_index = start_date.year * 12 + start_date.month - 1
        month_index = 0

        while len(results) < count:
            absolute_month = start_month_index + month_index * interval
            year, month_zero_based = divmod(absolute_month, 12)
            year += 0
            month = month_zero_based + 1
            _, last_day = calendar.monthrange(year, month)

            if len(parts) == 3:
                day_spec = int(parts[2])
                day = last_day if day_spec == -1 else day_spec
                if day <= last_day:
                    candidate = date(year, month, day)
                    if candidate >= start_date:
                        results.append(candidate.isoformat())
            else:
                n = int(parts[2])
                weekday = {
                    "MO": 0, "TU": 1, "WE": 2, "TH": 3,
                    "FR": 4, "SA": 5, "SU": 6,
                }[parts[3]]
                if n == -1:
                    last_weekday = date(year, month, last_day).weekday()
                    day = last_day - (last_weekday - weekday) % 7
                else:
                    first_weekday = date(year, month, 1).weekday()
                    day = 1 + (weekday - first_weekday) % 7 + (n - 1) * 7
                if day <= last_day:
                    candidate = date(year, month, day)
                    if candidate >= start_date:
                        results.append(candidate.isoformat())

            month_index += 1

    if kind == "YEARLY":
        month, day = map(int, parts[2].split("-"))
        year_index = 0
        while len(results) < count:
            year = start_date.year + year_index * interval
            try:
                candidate = date(year, month, day)
            except ValueError:
                candidate = None
            if candidate is not None and candidate >= start_date:
                results.append(candidate.isoformat())
            year_index += 1

    return results
